#include <bits/stdc++.h>
using namespace std;using ll=long long;
void req(bool p,string s){if(!p)throw runtime_error(s);}
vector<int> build(const vector<int>&s,int a,int m){int t=s.size(),n=2*t+m;vector<int>g(n);for(int u=0;u<n;u++)for(int v=u+1;v<n;v++){bool uv=false;if(v<t)uv=(s[u]>>v)&1;else if(u>=t&&v<2*t)uv=(s[v-t]>>(u-t))&1;else if(u<t&&v<2*t)uv=(u==a&&v-t==a);else if(u<t)uv=false;else if(u<2*t)uv=true;else uv=true;g[uv?u:v]|=1<<(uv?v:u);}return g;}
struct Counts{ll H=0,C=0,marked=0;};
Counts literal(const vector<int>&g,int x=-1,int y=-1){int n=g.size(),full=(1<<n)-1;Counts out;function<void(int,int,int,bool)>rec=[&](int first,int last,int mask,bool flag){if(mask==full){out.H++;out.marked+=flag;if(first==0&&(g[last]&1))out.C++;return;}for(int v=0;v<n;v++)if(!(mask>>v&1)&&(g[last]>>v&1))rec(first,v,mask|1<<v,flag||(last==x&&v==y));};for(int v=0;v<n;v++)rec(v,v,1<<v,false);return out;}
ll walkIE(const vector<int>&g){int n=g.size(),full=(1<<n)-1;ll ans=0;vector<ll>v(n),w(n);for(int mask=1;mask<=full;mask++){for(int i=0;i<n;i++)v[i]=(mask>>i)&1;for(int k=1;k<n;k++){fill(w.begin(),w.end(),0);for(int i=0;i<n;i++)if(v[i])for(int z=g[i]&mask;z;z&=z-1)w[__builtin_ctz((unsigned)z)]+=v[i];swap(v,w);}ll h=accumulate(v.begin(),v.end(),0LL);ans+=((n-__builtin_popcount((unsigned)mask))%2?-h:h);}return ans;}
int main(){ll roots=0,positive=0;for(int n=1;n<=4;n++){for(int code=0;code<(1<<(n*(n-1)/2));code++){vector<int>s(n);int p=0;for(int u=0;u<n;u++)for(int v=u+1;v<n;v++,p++){bool uv=(code>>p)&1;s[uv?u:v]|=1<<(uv?v:u);}int full=(1<<n)-1;vector<ll>hs(1<<n),ends(n),starts(n);hs[0]=1;vector<vector<ll>>ep(1<<n,vector<ll>(n));function<void(int,int,int)>rec=[&](int first,int last,int mask){hs[mask]++;ep[mask][last]++;if(mask==full){starts[first]++;ends[last]++;}for(int v=0;v<n;v++)if(!(mask>>v&1)&&(s[last]>>v&1))rec(first,v,mask|1<<v);};for(int v=0;v<n;v++)rec(v,v,1<<v);ll h=hs[full];for(int a=0;a<n;a++){ll q=0,d=0;for(int mask=1;mask<=full;mask++){ll z=ep[mask][a]*hs[full^mask];q+=z;d+=(__builtin_popcount((unsigned)mask)%2?-z:z);}req(d==-starts[a],"literal endpoint");auto g=build(s,a,0);auto c=literal(g,a,n+a);auto old=g;old[a]^=1<<(n+a);old[n+a]|=1<<a;auto loss=literal(old,n+a,a);req(c.H==h*h+q*q-starts[a]*starts[a],"zero formula");req(c.marked==q*q&&loss.marked==starts[a]*starts[a]&&loss.H==h*h,"literal gain loss");req(c.C==(n==1?0:ends[a]*ends[a]),"boundary cycle count");for(int m=1;m<=2;m++){auto f=literal(build(s,a,m));req(f.H==h*h+q*q*(1LL<<m)&&f.C==ends[a]*ends[a],"positive graph contrast");positive++;}roots++;}}}
cout<<"PASS literal_rooted_sides "<<roots<<" positive_graphs "<<positive<<"\n";
for(int k=1;k<=6;k++){int t=k+2;vector<int>s(t);for(int i=0;i<t;i++)for(int j=i+1;j<t;j++)s[i]|=1<<j;s[0]^=1<<(t-1);s[t-1]|=1;auto g=build(s,0,0);ll h=2*((1LL<<k)+1)*((1LL<<k)+1)-1;req(walkIE(g)==h,"independent walk inclusion exclusion");auto f=literal(g);req(f.H==h&&f.C==1,"literal family Hamilton paths/cycle");for(int u=0;u<2*t;u++)for(int v=0;v<2*t;v++)req(((g[u]>>v)&1)==((g[(v+t)%(2*t)]>>((u+t)%(2*t)))&1),"literal anti involution");cout<<"FAMILY "<<k<<" n "<<2*t<<" H "<<h<<" C "<<f.C;if(k==5){cout<<" rows";for(int x:g)cout<<" "<<x;}cout<<"\n";}
for(int p:{7,23,311}){for(int d=2;d*d<=p;d++)req(p%d!=0,"prime quotient");}req(8449==7*17*71,"composite quotient hostile");cout<<"PASS primes 7 23 311\n";}
